INSERT IGNORE INTO cursos (id, nome, descricao, short_descricao) VALUES
                                                                  (1, 'Arquitetura de Dados',
                                                                   'Aprenda a desenhar e modelar os ecossistemas de dados da sua organização de forma eficiente e segura.',
                                                                   'Neste curso, você mergulhará nos conceitos de governança, modelagem e integração de dados. Ideal para quem deseja projetar infraestruturas robustas que suportem a tomada de decisão estratégica e a análise avançada em grandes corporações.'),

                                                                  (2, 'Banco de Dados',
                                                                   'Domine o projeto, a criação e a administração de sistemas de gerenciamento de dados modernos e escaláveis.',
                                                                   'Explore a fundo os modelos relacionais e não relacionais. O curso abrange desde a modelagem entidade-relacionamento e normalização até a otimização de consultas complexas em SQL e a garantia de integridade das informações.'),

                                                                  (3, 'Banco de Dados e Armazenamento de Big Data',
                                                                   'Descubra como gerenciar e extrair valor de volumes massivos de dados com as tecnologias mais atuais do mercado.',
                                                                   'Uma formação voltada para os desafios do Big Data. Você aprenderá sobre data lakes, data warehouses, ecossistemas Hadoop e Spark, além de estratégias de armazenamento em nuvem para processamento de dados em larga escala.'),

                                                                  (4, 'Cibersegurança',
                                                                   'Proteja sistemas, redes e dados contra as mais avançadas ameaças e ataques digitais do mundo contemporâneo.',
                                                                   'Capacite-se para atuar na linha de frente da segurança da informação. O curso cobre análise de vulnerabilidades, criptografia, segurança de redes, políticas de acesso e resposta a incidentes de segurança cibernética.'),

                                                                  (5, 'Computação em Nuvem',
                                                                   'Aprenda a projetar e gerenciar infraestruturas escaláveis utilizando os principais provedores de nuvem do mercado.',
                                                                   'Explore os modelos IaaS, PaaS e SaaS. Você ganhará experiência prática em migração, arquitetura de alta disponibilidade e gestão de custos em ambientes cloud, preparando-se para as demandas da transformação digital.'),

                                                                  (6, 'Defesa Cibernética',
                                                                   'Torne-se um especialista em detectar, prevenir e neutralizar ataques no complexo espaço cibernético.',
                                                                   'Focado em segurança ofensiva e defensiva (Red Team/Blue Team), o curso ensina técnicas de pentest, forense digital, monitoramento contínuo e inteligência de ameaças para proteger infraestruturas críticas.'),

                                                                  (7, 'Desenvolvimento de Banco de Dados',
                                                                   'Eleve suas habilidades em programação e otimização avançada para bancos de dados corporativos.',
                                                                   'Vá além da administração básica. Aprenda a escrever procedures complexas, triggers, funções, e a realizar tunning de performance para garantir que aplicações de alto tráfego rodem sem gargalos de dados.'),

                                                                  (8, 'Desenvolvimento de Software',
                                                                   'Aprenda os fundamentos e as melhores práticas para planejar, criar e testar sistemas computacionais.',
                                                                   'Uma visão abrangente da engenharia de software clássica e moderna. O aluno passará pelo ciclo de vida completo: levantamento de requisitos, design de padrões (Design Patterns), codificação estruturada e testes de qualidade.'),

                                                                  (9, 'Desenvolvimento de Software para Comércio Eletrônico',
                                                                   'Crie plataformas de vendas online escaláveis, seguras e focadas na melhor experiência de conversão.',
                                                                   'Estude arquiteturas de e-commerce, integração com gateways de pagamento de terceiros, gestão de carrinhos, segurança de transações (PCI DSS) e estratégias de SEO técnico para lojas virtuais.'),

                                                                  (10, 'Desenvolvimento Full Stack',
                                                                   'Domine tanto a criação de interfaces incríveis quanto a lógica de servidores, tornando-se um desenvolvedor completo.',
                                                                   'Este curso une o melhor dos dois mundos. Você aprenderá HTML, CSS e frameworks JavaScript no front-end, integrados a linguagens de back-end (como Node.js, Python ou Java) e bancos de dados, construindo aplicações de ponta a ponta.'),

                                                                  (11, 'Desenvolvimento Mobile',
                                                                   'Aprenda a construir aplicativos inovadores e de alta performance para smartphones e tablets.',
                                                                   'Mergulhe no ecossistema de dispositivos móveis. O curso aborda design de interfaces responsivas (UI/UX mobile), consumo de APIs RESTful, armazenamento local e publicação nas lojas de aplicativos (App Store e Google Play).'),

                                                                  (12, 'Engenharia de Software',
                                                                   'Lidere a construção de sistemas complexos com metodologias ágeis, qualidade e arquitetura de alto nível.',
                                                                   'Foco na gestão e estruturação do software em larga escala. Aborda métricas de qualidade, integração e entrega contínuas (CI/CD), gestão de times de desenvolvimento e adoção de práticas DevOps no ciclo de vida do produto.'),

                                                                  (13, 'Gestão da Segurança e Defesa Cibernética',
                                                                   'Prepare-se para liderar times e definir as estratégias corporativas de proteção de dados e ativos digitais.',
                                                                   'Voltado para futuros CISOs e gestores. Aprenda sobre frameworks de governança (ISO 27001, NIST), compliance (LGPD/GDPR), gestão de riscos de TI e elaboração de planos de continuidade de negócios (BCP).'),

                                                                  (14, 'Gestão da Tecnologia da Informação',
                                                                   'Aprenda a alinhar os recursos de tecnologia aos objetivos estratégicos e de negócios da sua empresa.',
                                                                   'Desenvolva habilidades em governança de TI (ITIL, COBIT), gestão de portfólio de projetos tecnológicos, liderança de equipes multidisciplinares e planejamento estratégico para impulsionar a inovação corporativa.'),

                                                                  (15, 'Gestão de Ambientes Internet e Redes de Computadores',
                                                                   'Domine a administração de infraestruturas conectadas, garantindo alta disponibilidade e performance.',
                                                                   'Aprenda a monitorar e manter servidores web, gerenciar tráfego de redes, configurar firewalls e balanceadores de carga, assegurando que os serviços online operem de forma contínua e segura.'),

                                                                  (16, 'Gestão de Internet e Redes de Computadores',
                                                                   'Desenvolva expertise técnica para planejar, implantar e operar redes corporativas robustas.',
                                                                   'O curso foca em protocolos TCP/IP, roteamento avançado, comutação de pacotes (switching) e administração de redes locais (LAN) e de longa distância (WAN), preparando o aluno para certificações reconhecidas pelo mercado.'),

                                                                  (17, 'Gestão de Redes de Computadores e Internet',
                                                                   'Capacite-se para gerir a conectividade empresarial com foco em eficiência, segurança e inovação.',
                                                                   'Além da base técnica em redes, este curso aborda a gestão de serviços de infraestrutura, tecnologias sem fio (Wireless), redes definidas por software (SDN) e a integração de conectividade com serviços em nuvem.'),

                                                                  (18, 'Internet das Coisas',
                                                                   'Descubra como conectar o mundo físico ao digital criando soluções inteligentes e automatizadas.',
                                                                   'Explore a arquitetura IoT: sensores, microcontroladores (como Arduino e Raspberry Pi), protocolos de comunicação M2M (MQTT, CoAP), edge computing e análise em tempo real dos dados gerados por dispositivos conectados.'),

                                                                  (19, 'Produção de Software',
                                                                   'Domine os processos e ferramentas necessárias para entregar produtos de software com qualidade e no prazo.',
                                                                   'Um curso com forte viés prático sobre o fluxo de esteiras de desenvolvimento. Envolve versionamento de código (Git), automação de build, testes automatizados e o gerenciamento eficiente de backlogs e releases.'),

                                                                  (20, 'Programação de Sistemas',
                                                                   'Aprenda a base da computação, desenvolvendo algoritmos eficientes e softwares que interagem diretamente com o hardware.',
                                                                   'Foco no desenvolvimento de baixo a médio nível. Você estudará linguagens como C ou C++, manipulação de memória, concorrência, sistemas operacionais e a criação de utilitários de alta performance.'),

                                                                  (21, 'Redes de Computadores',
                                                                   'Compreenda a fundo como a internet e as redes corporativas funcionam, desde os cabos até os protocolos de aplicação.',
                                                                   'Estudo detalhado do modelo OSI e da arquitetura TCP/IP. Aprenda sobre cabeamento estruturado, configuração de roteadores e switches, análise de tráfego e resolução de problemas (troubleshooting) de conectividade.'),

                                                                  (22, 'Segurança Cibernética',
                                                                   'Torne-se a principal barreira entre cibercriminosos e as informações sensíveis da sua organização.',
                                                                   'Um mergulho técnico nas defesas digitais. Aprenda a auditar sistemas, aplicar hardening em servidores, utilizar ferramentas de detecção de intrusão (IDS/IPS) e mitigar ataques de engenharia social e malware.'),

                                                                  (23, 'MBA em Agrotech Leadership: Tecnologia, Liderança & Sustentabilidade no Agronegócio',
                                                                   'Lidere a transformação digital no campo, unindo inovações tecnológicas à sustentabilidade do agronegócio.',
                                                                   'Formação executiva de alto nível. Discute o uso de IoT, drones, big data e IA na agricultura de precisão, combinados com estratégias de liderança moderna, ESG e gestão da cadeia produtiva agrícola.'),

                                                                  (24, 'AI Scientist',
                                                                   'Domine a criação e o treinamento de modelos avançados de Inteligência Artificial para resolver problemas complexos.',
                                                                   'Voltado para quem quer estar na fronteira da tecnologia. Aprofunde-se em redes neurais profundas (Deep Learning), processamento de linguagem natural (NLP), visão computacional e algoritmos generativos usando Python e frameworks como TensorFlow ou PyTorch.'),

                                                                  (25, 'Análise e Projeto de Software',
                                                                   'Aprenda a traduzir necessidades complexas de negócios em especificações técnicas claras e arquiteturas funcionais.',
                                                                   'Especialização em engenharia de requisitos e modelagem visual. Utilizando UML e metodologias ágeis, você aprenderá a desenhar casos de uso, diagramas de classe e arquiteturas que garantam o sucesso do desenvolvimento.'),

                                                                  (26, 'Desenvolvimento em Aplicações Web',
                                                                   'Construa sites e sistemas para internet modernos, interativos e focados na experiência do usuário.',
                                                                   'Abrange as tecnologias essenciais da web moderna. O aluno aprenderá a criar interfaces ricas, integrar formulários com back-ends via APIs e aplicar boas práticas de acessibilidade e web semântica.'),

                                                                  (27, 'Desenvolvimento Mobile com Ênfase em Flutter',
                                                                   'Crie aplicativos nativos para Android e iOS a partir de um único código-base usando o framework do Google.',
                                                                   'Aprenda a linguagem Dart e o ecossistema Flutter. O curso ensina a criar interfaces expressivas com widgets, gerenciar estados de forma eficiente e consumir dados externos para entregar apps de altíssima performance.'),

                                                                  (28, 'Desenvolvimento Mobile com Ênfase em Ionic',
                                                                   'Utilize seus conhecimentos web (HTML, CSS e JS) para desenvolver aplicativos móveis híbridos de forma ágil.',
                                                                   'Foco em produtividade multiplataforma. Aprenda a usar o Ionic Framework em conjunto com Angular ou React para criar apps que rodam em Android, iOS e web (PWA), aproveitando componentes nativos via Capacitor/Cordova.'),

                                                                  (29, 'Desenvolvimento Mobile com Ênfase em React',
                                                                   'Domine o React Native para construir aplicativos móveis dinâmicos utilizando a biblioteca JavaScript mais popular do mundo.',
                                                                   'O curso aprofunda os conceitos do React aplicados ao mobile. Você aprenderá sobre hooks, navegação nativa, animações fluidas e como integrar bibliotecas de terceiros para recursos de câmera, mapas e geolocalização.'),

                                                                  (30, 'Desenvolvimento Mobile com Ênfase em Xamarin',
                                                                   'Crie aplicativos corporativos multiplataforma robustos utilizando C# e todo o ecossistema .NET.',
                                                                   'Ideal para desenvolvedores Microsoft. Aprenda a compartilhar lógica de negócios entre iOS e Android, construir interfaces com XAML usando Xamarin.Forms (ou .NET MAUI) e integrar o app de forma nativa aos recursos dos dispositivos.'),

                                                                  (31, 'Desenvolvimento Mobile e IoT',
                                                                   'Aprenda a conectar aplicativos de celular a dispositivos inteligentes, criando automações no mundo físico.',
                                                                   'Explore a união de duas áreas em alta. O curso ensina a construir apps móveis que se comunicam via Bluetooth (BLE), Wi-Fi ou nuvem com placas de prototipagem e sensores para soluções de smart home, saúde ou indústria.'),

                                                                  (32, 'Desenvolvimento Web Full Stack',
                                                                   'Seja o profissional capaz de criar desde o banco de dados até a interface final de uma aplicação web completa.',
                                                                   'Mergulho intenso no desenvolvimento end-to-end. Você criará APIs robustas no back-end, modelará dados em bancos SQL/NoSQL e desenvolverá interfaces reativas usando frameworks modernos no front-end, tudo com controle de versão.'),

                                                                  (33, 'Desenvolvimento Web Back-End',
                                                                   'Domine a lógica, a segurança e a gestão de dados nos bastidores das aplicações web de sucesso.',
                                                                   'Foco exclusivo na infraestrutura invisível aos usuários. Aprenda sobre arquitetura de microsserviços, criação de APIs RESTful e GraphQL, autenticação (OAuth, JWT) e testes automatizados de integração e unidade.'),

                                                                  (34, 'Desenvolvimento Web Front-End',
                                                                   'Crie interfaces visuais surpreendentes, acessíveis e altamente performáticas para a web moderna.',
                                                                   'Especialize-se na camada de apresentação. O curso cobre HTML5 avançado, CSS3 (Flexbox, Grid, pré-processadores), JavaScript moderno (ES6+) e o uso de bibliotecas de componentes para criar Single Page Applications (SPAs).'),

                                                                  (35, 'Desenvolvimento Web Mobile',
                                                                   'Aprenda a criar aplicações web (PWA) que se comportam como aplicativos nativos nos celulares dos usuários.',
                                                                   'Foco em performance e usabilidade móvel. Estude técnicas de design mobile-first, uso de service workers para funcionamento offline, notificações push na web e otimização de velocidade de carregamento (Web Vitals).'),

                                                                  (36, 'Desenvolvimento Web com Ênfase em Angular',
                                                                   'Domine um dos frameworks front-end corporativos mais poderosos do mercado, mantido pelo Google.',
                                                                   'Aprenda a criar Single Page Applications (SPAs) escaláveis usando TypeScript. O curso aborda a arquitetura baseada em componentes, injeção de dependência, roteamento avançado, formulários reativos e consumo de APIs via RxJS.'),

                                                                  (37, 'Desenvolvimento Web com Ênfase em MDL',
                                                                   'Descubra como aplicar as diretrizes do Material Design Lite para interfaces limpas e intuitivas na web.',
                                                                   'Focado em design de interação e UI. Você aprenderá a implementar componentes visuais padronizados pelo Google (botões, cards, menus) sem depender de frameworks pesados, garantindo consistência visual em projetos web.'),

                                                                  (38, 'Desenvolvimento Web com Ênfase em PHP',
                                                                   'Construa sistemas back-end robustos utilizando a linguagem que movimenta grande parte da web mundial.',
                                                                   'Do básico ao avançado em PHP. O curso aborda a orientação a objetos, o padrão MVC, acesso seguro a bancos de dados com PDO e o uso de frameworks modernos como Laravel ou Symfony para acelerar o desenvolvimento.'),

                                                                  (39, 'Desenvolvimento Web com Ênfase em Python',
                                                                   'Aprenda a desenvolver back-ends poderosos e escaláveis utilizando a versatilidade da linguagem Python.',
                                                                   'Explore frameworks consolidados como Django ou Flask. O curso ensina a criar aplicações com rápida prototipagem, integradas com bancos de dados (ORM), painéis administrativos automatizados e segurança nativa contra vulnerabilidades web.'),

                                                                  (40, 'Desenvolvimento Full Stack Web, DevOps Aplicados a Produto e Inteligência Artificial',
                                                                   'A formação definitiva: una criação de software, operações automatizadas e IA para inovar em produtos digitais.',
                                                                   'Um curso multidisciplinar avançado. Você desenvolverá aplicações completas, criará pipelines de CI/CD para deploy contínuo e integrará APIs de Inteligência Artificial e Machine Learning diretamente no seu produto de software.'),

                                                                  (41, 'Desenvolvimento Full Stack e IoT',
                                                                   'Aprenda a construir plataformas web completas que recebem, processam e exibem dados de dispositivos da Internet das Coisas.',
                                                                   'Uma abordagem sistêmica. No back-end, você criará brokers e APIs para receber dados de sensores; no banco de dados, aprenderá a armazenar séries temporais; e no front-end, construirá dashboards em tempo real para monitorar a frota IoT.'),

                                                                  (42, 'Desenvolvimento Java e .NET',
                                                                   'Torne-se especialista nas duas plataformas de desenvolvimento corporativo mais requisitadas por grandes empresas.',
                                                                   'Formação dupla e robusta. Você aprenderá as nuances do Java (Spring Boot) e do C# (.NET Core), permitindo que você atue em sistemas empresariais legados e em arquiteturas modernas baseadas em microsserviços de alto desempenho.'),

                                                                  (43, 'Data Science e Analytics Aplicado a Finanças',
                                                                   'Utilize o poder dos dados para modelar riscos, prever tendências e otimizar carteiras no mercado financeiro.',
                                                                   'Focado no setor econômico. Aprenda séries temporais, modelos de risco de crédito, detecção de fraudes financeiras e algoritmos preditivos usando Python e R, voltados para fintechs e bancos tradicionais.'),

                                                                  (44, 'Data Science e Big Data Aplicados à Indústria',
                                                                   'Transforme o chão de fábrica liderando projetos de Indústria 4.0 baseados em análise de dados massivos.',
                                                                   'Otimize a produção com dados. O curso foca em manutenção preditiva utilizando IoT, análise de qualidade em tempo real, pesquisa operacional e otimização de cadeias de suprimentos baseada em algoritmos de machine learning.'),

                                                                  (45, 'Desenvolvimento de Sistemas',
                                                                   'Domine os princípios e as técnicas para construir softwares que resolvem problemas reais de forma estruturada.',
                                                                   'Um curso generalista e aprofundado. Engloba lógica de programação, banco de dados, análise orientada a objetos e práticas de codificação limpa (Clean Code), dando autonomia para atuar em diferentes linguagens e projetos.'),

                                                                  (46, 'Desenvolvimento de Software com Metodologia Ágil',
                                                                   'Aprenda a programar e entregar software de forma iterativa, adaptando-se rapidamente às mudanças de requisitos.',
                                                                   'União entre técnica e gestão. Você programará dentro de sprints simuladas, utilizando práticas do Scrum, TDD (Desenvolvimento Orientado a Testes), pair programming e revisão de código para garantir entregas frequentes e de valor.'),

                                                                  (47, 'Desenvolvimento de Software com Metodologias Ágeis',
                                                                   'Especialize-se na aplicação de múltiplos frameworks ágeis para escalar o desenvolvimento em equipes de alto desempenho.',
                                                                   'Aprofundamento em agilidade corporativa. Além do Scrum, o curso aborda Kanban, Lean Software Development e SAFe, focando na eliminação de desperdícios e na maximização do fluxo de entrega de valor no ciclo de vida do software.'),

                                                                  (48, 'Desenvolvimento de Games',
                                                                   'Aprenda todo o processo criativo e técnico para transformar suas ideias em jogos digitais completos e divertidos.',
                                                                   'Uma visão 360º da produção de jogos. Inclui game design, roteiro, level design, modelagem/animação básica, e introdução à programação em motores gráficos de mercado, cobrindo o ciclo da pré-produção ao lançamento.'),

                                                                  (49, 'Desenvolvedor de Jogos',
                                                                   'Foque intensamente na programação e lógica para dar vida a mecânicas complexas, inteligência artificial e física em jogos.',
                                                                   'O curso para quem quer escrever código em games. Aborda matemática aplicada a gráficos (vetores, matrizes), otimização de performance, criação de scripts de IA para NPCs e física computacional utilizando C++ ou C#.'),

                                                                  (50, 'Desenvolvimento Avançado em Go',
                                                                   'Domine a linguagem criada pelo Google para construir sistemas e microsserviços de alta concorrência e escalabilidade.',
                                                                   'Explore as goroutines e canais do Golang. O curso é focado em desenvolvedores que buscam criar APIs ultrarrápidas, ferramentas de linha de comando CLI, e sistemas para computação em nuvem que exigem baixo consumo de recursos.'),

                                                                  (51, 'Desenvolvimento de Aplicações Corporativas Java',
                                                                   'Especialize-se na criação de arquiteturas empresariais seguras, distribuídas e escaláveis com o ecossistema Java.',
                                                                   'Voltado para aplicações de missão crítica. Aprenda arquitetura hexagonal, Spring Framework (Boot, Security, Data), mensageria (Kafka/RabbitMQ) e conteinerização (Docker) aplicados a contextos corporativos de larga escala.'),

                                                                  (52, 'Criptografia Digital com Ênfase em Blockchain',
                                                                   'Entenda a matemática e a segurança por trás das tecnologias de registros distribuídos e criptomoedas.',
                                                                   'Mergulhe na base da Web3. O curso ensina algoritmos de hash (SHA-256), criptografia assimétrica, árvores de Merkle, mecanismos de consenso e a aplicação prática dessas técnicas na construção e auditoria de redes blockchain.'),

                                                                  (53, 'Criptografia, Assinatura Digital e Documento Eletrônico',
                                                                   'Aprenda a garantir a validade jurídica, autenticidade e integridade das informações no meio digital.',
                                                                   'Foco em segurança de documentos. Aborda a infraestrutura de chaves públicas (ICP-Brasil), padrões de assinatura digital, certificação digital e as normativas legais que regulamentam transações e contratos eletrônicos seguros.'),

                                                                  (54, 'Criptografia, Assinatura Eletrônica e Documento Digital',
                                                                   'Capacite-se na implementação de sistemas que protegem e validam a identidade e os dados em transações digitais.',
                                                                   'Estudo aplicado sobre controle de acesso, não repúdio e confidencialidade. O aluno aprenderá a integrar APIs de assinatura digital em sistemas de ERP e plataformas web, garantindo segurança corporativa e conformidade legal.'),

                                                                  (55, 'Curso de Especialização em Big Data & Analytics',
                                                                   'Domine o ciclo completo dos dados, da extração à visualização estratégica para alavancar negócios.',
                                                                   'Formação analítica completa. Envolve engenharia de dados (pipelines de ETL/ELT), análise exploratória, ferramentas de visualização interativa (Power BI, Tableau) e storytelling com dados para apoiar tomadores de decisão.'),

                                                                  (56, 'Ciência de Dados e Big Data com Ênfase em Docência do Ensino Superior',
                                                                   'Prepare-se para pesquisar e lecionar sobre tecnologias de dados nas melhores universidades e instituições de ensino.',
                                                                   'União entre tecnologia e pedagogia acadêmica. Além dos conhecimentos avançados em machine learning e análise de dados massivos, o curso desenvolve habilidades didáticas, metodologia científica e práticas de ensino superior.'),

                                                                  (57, 'Cloud & AI DevOps',
                                                                   'Automatize pipelines inteligentes integrando infraestrutura em nuvem, práticas DevOps e serviços de Inteligência Artificial.',
                                                                   'O futuro das operações de TI (AIOps). Aprenda Infraestrutura como Código (Terraform, Ansible), orquestração contínua e como automatizar o deploy e monitoramento de modelos de Machine Learning (MLOps) em ambientes cloud.'),

                                                                  (58, 'Cloud Services com Ênfase em Google Engine',
                                                                   'Torne-se especialista em desenhar, configurar e gerenciar infraestruturas escaláveis no Google Cloud Platform (GCP).',
                                                                   'Foco prático nos serviços do Google. Aprenda a utilizar o Compute Engine, App Engine, Cloud Storage, BigQuery e ferramentas de rede e segurança do GCP para hospedar aplicações modernas e nativas da nuvem.'),

                                                                  (59, 'Cloud Services com Ênfase em Kubernetes',
                                                                   'Domine a principal plataforma de orquestração de contêineres do mercado para garantir a escalabilidade dos seus microsserviços.',
                                                                   'O padrão ouro da infraestrutura moderna. O curso aborda a arquitetura de clusters Kubernetes (K8s), deployments, pods, services, ingress controllers, gestão de secrets e estratégias avançadas de atualização sem downtime (Zero Downtime Deploy).'),

                                                                  (60, 'Cloud Services com Ênfase em Microsoft Azure',
                                                                   'Aprenda a construir, migrar e gerenciar soluções e aplicativos na robusta plataforma de nuvem da Microsoft.',
                                                                   'Especialização no ecossistema Azure. Aborda Máquinas Virtuais, Azure App Services, Azure SQL, Active Directory (Entra ID) em nuvem, e práticas de arquitetura utilizando o Microsoft Cloud Adoption Framework para empresas.'),

                                                                  (61, 'Computação Quântica',
                                                                   'Descubra a próxima revolução tecnológica aprendendo os fundamentos e algoritmos do processamento de dados quântico.',
                                                                   'Introdução à nova era da computação. O curso desmistifica qubits, superposição, emaranhamento e portões lógicos quânticos, ensinando a utilizar frameworks modernos (como Qiskit) para programar simuladores e computadores quânticos reais.'),

                                                                  (62, 'Arquitetura da Informação e Experiência do Usuário',
                                                                   'Aprenda a estruturar o conteúdo e desenhar jornadas digitais focadas em usabilidade e na satisfação do usuário (UX).',
                                                                   'Conecte negócios, usuários e tecnologia. O curso ensina metodologias de pesquisa com usuários (User Research), card sorting, taxonomia, wireframing, prototipação e testes de usabilidade para criar produtos digitais centrados no ser humano.'),

                                                                  (63, 'Arquitetura da Informação: Design de Interação Digital',
                                                                   'Especialize-se na criação de interfaces visuais intuitivas e microinterações que engajam o usuário.',
                                                                   'Foco em UI e Interação. Aprenda sobre hierarquia visual, tipografia, psicologia das cores, animações funcionais e design de estados, garantindo que o fluxo de uso da aplicação seja fluido, lógico e esteticamente agradável.'),

                                                                  (64, 'Arquitetura de Computação em Nuvem',
                                                                   'Desenhe e planeje infraestruturas tecnológicas resilientes, seguras e com excelente custo-benefício na nuvem.',
                                                                   'Formação para Arquitetos de Nuvem. Aprenda padrões de arquitetura distribuída, recuperação de desastres (Disaster Recovery), modelos multi-cloud/híbridos e como traduzir os requisitos de negócio em topologias de rede eficientes na nuvem.'),

                                                                  (65, 'Arquitetura de Redes e Cloud Computing',
                                                                   'Una o conhecimento tradicional de infraestrutura física à flexibilidade e escalabilidade das plataformas em nuvem.',
                                                                   'Para profissionais que gerenciam a transição digital. Aborda redes definidas por software (SDN), VPNs site-to-site, roteamento híbrido (BGP) e a integração segura entre os datacenters on-premise da empresa e a nuvem pública.'),

                                                                  (66, 'Arquitetura de Sistemas',
                                                                   'Capacite-se para definir e integrar os componentes, módulos e infraestrutura que compõem sistemas de grande porte.',
                                                                   'Visão macro do desenvolvimento. O curso foca em integração de sistemas, APIs, arquiteturas orientadas a serviços (SOA) e a microsserviços, mensageria assíncrona e escolhas tecnológicas estratégicas (Trade-offs arquiteturais).'),

                                                                  (67, 'Arquitetura de Software',
                                                                   'Aprenda a tomar as decisões técnicas fundamentais para garantir a manutenibilidade, segurança e performance do código.',
                                                                   'Para desenvolvedores seniores. Estude padrões de projeto (Design Patterns), princípios SOLID, Clean Architecture, Domain-Driven Design (DDD) e métricas para evitar dívida técnica e manter a base de código escalável ao longo dos anos.'),

                                                                  (68, 'Arquitetura e Gestão de Infraestrutura em TI',
                                                                   'Domine o planejamento e a governança de todos os ativos de tecnologia, garantindo operações contínuas e eficientes.',
                                                                   'Gestão completa do datacenter. O curso aborda virtualização de servidores, armazenamento (SAN/NAS), backup corporativo, eficiência energética e a aplicação de frameworks de gestão de serviços de TI (ITSM).'),

                                                                  (69, 'Administração de Serviços Linux',
                                                                   'Torne-se especialista em operar, configurar e proteger servidores utilizando o sistema operacional mais usado em datacenters.',
                                                                   'Formação "mão na massa" via terminal. Aprenda gerenciamento de pacotes, permissões avançadas, shell scripting para automação de tarefas, configuração de serviços essenciais (Apache/Nginx, SSH, DNS) e hardening de sistemas Linux.'),

                                                                  (70, 'Agile Project Management',
                                                                   'Domine frameworks ágeis para gerenciar projetos, priorizar entregas e liderar equipes em ambientes dinâmicos.',
                                                                   'Foco em gestão iterativa. O curso ensina o papel do Scrum Master e do Product Owner, práticas de refinamento de backlog, estimativas ágeis (Planning Poker) e a gestão visual de fluxo de trabalho para acelerar entregas de valor.'),

                                                                  (71, 'Agile Project Management & Business Agility',
                                                                   'Leve a mentalidade ágil muito além dos times de TI, transformando a estrutura e a cultura de toda a sua organização.',
                                                                   'Estratégia corporativa de adaptação. Aprenda como escalar a agilidade envolvendo áreas de negócio (RH, Marketing, Financeiro), utilizando métricas de fluxo, OKRs, e promovendo uma cultura de experimentação e inovação contínua.'),

                                                                  (72, 'Algoritmos e Lógica de Programação',
                                                                   'Construa a fundação essencial do raciocínio analítico computacional para resolver problemas através do código.',
                                                                   'O primeiro passo de qualquer desenvolvedor. O curso desmistifica a programação usando pseudocódigo e linguagens iniciais, ensinando variáveis, laços de repetição, estruturas condicionais e funções de forma clara e didática.'),

                                                                  (73, 'Análise de Dados e Inteligência Artificial',
                                                                   'Aprenda a transformar dados brutos em decisões estratégicas utilizando poderosos algoritmos preditivos.',
                                                                   'Combinando análise e IA. O curso ensina desde a limpeza e preparação de dados até a aplicação de técnicas supervisionadas e não supervisionadas de machine learning para identificar padrões ocultos e prever cenários futuros.'),

                                                                  (74, 'Análise de Dados e Matemática Aplicada',
                                                                   'Aprofunde-se nos fundamentos estatísticos e matemáticos rigorosos que validam a ciência de dados.',
                                                                   'Para quem busca o rigor científico. O curso aborda álgebra linear, cálculo multivariável, probabilidade e inferência estatística, essenciais para compreender *como* os algoritmos de dados funcionam por baixo dos panos.'),

                                                                  (75, 'Desenvolvimento de Games com Ênfase em Unity',
                                                                   'Crie jogos interativos e mundos virtuais em 2D ou 3D utilizando a versátil e popular engine Unity.',
                                                                   'Aprenda programação em C# voltada para games. O curso aborda o uso do editor da Unity, física 2D/3D, sistema de partículas, UI de jogos, animações e a exportação do seu projeto para múltiplas plataformas (PC, consoles, mobile).'),

                                                                  (76, 'Desenvolvimento de Games com Ênfase em Unreal',
                                                                   'Desenvolva jogos, simulações realistas e experiências imersivas de alta fidelidade visual com a Unreal Engine.',
                                                                   'O padrão da indústria AAA. Explore a programação visual via Blueprints e a codificação avançada em C++, além de técnicas de iluminação, renderização fotorrealista, shaders e o ecossistema de assets da Epic Games.'),

                                                                  (77, 'Desenvolvimento de Games e Aplicativos Móveis',
                                                                   'Atue no lucrativo mercado de entretenimento mobile criando aplicativos lúdicos e jogos casuais otimizados.',
                                                                   'Interseção entre software e entretenimento. O curso foca em mecânicas de jogos hiper-casuais, monetização (Ads, In-App Purchases), otimização de bateria e performance gráfica adaptada às restrições de dispositivos móveis.'),

                                                                  (78, 'Aprendizado de Máquina (Machine Learning)',
                                                                   'Domine a tecnologia por trás das IAs ensinando computadores a reconhecer padrões e aprender com a experiência.',
                                                                   'Aprofundamento prático. O aluno construirá modelos de regressão, classificação e clusterização utilizando a biblioteca Scikit-Learn (Python), aprendendo a avaliar a precisão dos modelos e evitar problemas como o overfitting.'),

                                                                  (79, 'Cibersegurança: Governança e Gestão',
                                                                   'Aprenda a alinhar as defesas técnicas às normas legais, mitigando riscos institucionais e garantindo compliance.',
                                                                   'Focado na gestão de riscos e processos. Ensina a criar políticas de segurança da informação, conduzir auditorias de TI, adequar a empresa a leis de privacidade e estabelecer indicadores de desempenho (KPIs) para a área de segurança.'),

                                                                  (80, 'Ciência de Dados com Ênfase em Blockchain',
                                                                   'Extraia, audite e analise dados valiosos que estão armazenados de forma descentralizada nas redes de criptomoedas.',
                                                                   'Uma especialização pioneira. O curso ensina a ler dados on-chain, analisar o comportamento de carteiras, rastrear fluxos financeiros em ledgers distribuídos e aplicar machine learning em dados de smart contracts e protocolos DeFi.'),

                                                                  (81, 'Ciência de Dados e Inteligência Artificial',
                                                                   'Formação completa que une engenharia de dados, estatística complexa e a arquitetura de redes neurais profundas.',
                                                                   'Do dado bruto ao modelo generativo. O aluno passará por todas as etapas de um projeto de dados avançado, construindo desde pipelines de processamento até o deploy de modelos preditivos e sistemas de recomendação em produção.'),

                                                                  (82, 'Ciência de Dados e Saúde Digital',
                                                                   'Utilize análise de dados de ponta para inovar em tratamentos, processos médicos e sistemas de saúde inteligentes.',
                                                                   'Data Science na área médica. O curso aborda a padronização de registros eletrônicos de saúde, predição de surtos epidemiológicos, análise de imagens médicas (com visão computacional) e a ética no tratamento de dados de pacientes.'),

                                                                  (83, 'Ciência de Dados para Humanidades',
                                                                   'Descubra como os métodos computacionais estão revolucionando a análise de tendências sociológicas e históricas.',
                                                                   'Tecnologia encontra ciências sociais. Aprenda web scraping, processamento de linguagem natural e análise de redes sociais para analisar discursos públicos, estudar movimentos culturais e processar grandes acervos de dados históricos.')